using System;
using System.IO;
using VM.GlobalScript.Methods;
using VM.Core;
using VM.PlatformSDKCS;

public class UserGlobalScript : UserGlobalMethods, IScriptMethods
{
    public int Init()
    {
        return InitSDK();
    }

    public override int InitAfterLoadSol()
    {
        string solutionPath = VmSolution.Instance.SolutionPath;
        SetGlobalVariableStringValue("SolutionName", Path.GetFileNameWithoutExtension(solutionPath));
        SetGlobalVariableStringValue("SolutionDirectory", Path.GetDirectoryName(solutionPath));
        foreach (string processName in dictProcessID.Keys)
        {
            VmProcedure procedure = VmSolution.Instance[processName] as VmProcedure;
            if (procedure != null)
            {
                procedure.LocalVariable.SetVarString("ProcedureName", new string[] { processName });
            }
        }
        return 0;
    }

    public int Process()
    {
        return 0;
    }
}
